function queueCard(item) { const housekeepingActions = { Schedule: 'Complete Housekeeping - Review of Internal / Office accounts', Scheduled: 'Complete Housekeeping - Review of Internal / Office accounts', Overdue: 'Complete Housekeeping - Review of Internal / Office accounts', WIP: 'Continue Housekeeping - Review of Internal / Office accounts', 'Pending AM Review': 'View Housekeeping - Review of Internal / Office accounts', 'Pending Audit Manager Review': 'View Housekeeping - Review of Internal / Office accounts', 'Rework Required': 'Complete Rework on Housekeeping - Review of Internal / Office accounts', 'Resubmitted for Review': 'View Housekeeping - Review of Internal / Office accounts', Completed: 'View Housekeeping - Review of Internal / Office accounts' }; const actionLabel = queueMode === 'housekeeping' ? housekeepingActions[item.status] : actions[item.status]; const period = queueMode === 'housekeeping' ? 'Housekeeping - Review of Internal / Office accounts Month' : 'Audit Week'; const start = queueMode === 'housekeeping' ? '2026-08-24' : item.start; const due = queueMode === 'housekeeping' ? '29 Aug 2026' : item.due; const startLabel = queueMode === 'housekeeping' ? 'Start Date' : 'Audit Start Date'; const dueLabel = queueMode === 'housekeeping' ? 'Due Date' : (item.status === 'Overdue' ? 'Original Due Date' : 'Audit Due Date'); return `<article class="app-card"><div class="card-line"><span class="code-pill">${item.code}</span><span class="status-pill ${statusClass(item.status)}"><i></i>${item.status}</span></div><h3>${item.name}</h3><p>${period}: <b>${queueMode === 'housekeeping' ? '24 Aug - 29 Aug 2026' : item.week}</b></p><p>${startLabel}: <b>${start}</b></p><p class="muted">${dueLabel}: <b>${due}</b></p>${item.overdue ? `<p class="overdue-days">${item.overdue}</p>` : ''}${actionLabel ? `<button class="btn primary" data-branch="${item.code}">${actionLabel}</button>` : ''}</article>`; }
