function managerPage() { const rows = managerRecords.map((item, index) => `<tr data-manager-status="${item.status}"><td>${index + 1}</td><td><b>${item.branch}</b></td><td>${item.code}</td><td>${item.week}</td><td>${item.start}</td><td>${item.due}</td><td>${item.auditor}</td><td><span class="status-pill ${statusClass(item.status)}"><i></i>${item.status}</span></td><td>${item.submitted}</td><td>${item.updated}</td><td><button class="link-btn manager-review" data-go="15-review-audit-list-manager">${item.status === 'Completed' ? 'View Audit' : item.status === 'Rework Required' ? 'View / Review Audit' : 'Review Audit'}</button></td></tr>`).join(''); return `<div class="page-heading"><div><span class="eyebrow">AUDIT MANAGER / MONITORING</span><h1>List My Assigned Entities</h1><p>Audits assigned to your team for review and monitoring</p></div><span class="total-chip">${managerRecords.length} audits</span></div><div class="filters manager-filters"><label class="search"><span>⌕</span><input id="managerSearch" placeholder="Search Branch / Branch Code / Auditor"></label><label>From Date<input id="managerFrom" value="01-Apr-2026"></label><label>To Date<input id="managerTo" value="23-Aug-2026"></label><button class="btn primary" id="managerApply">Apply</button><button class="btn secondary" id="managerReset">Reset</button></div><div class="status-tabs manager-tabs">${managerStatuses.map((status, index) => `<button class="manager-tab ${index === 0 ? 'selected' : ''}" data-manager-tab="${status}">${status}<span>${status === 'All' ? managerRecords.length : managerRecords.filter(item => item.status === status).length}</span></button>`).join('')}</div><div class="table-wrap manager-table"><table><thead><tr><th>Sr. No.</th><th>Branch Name</th><th>Branch Code</th><th>Audit Week</th><th>Audit Start Date</th><th>Audit Due Date</th><th>Auditor Name</th><th>Audit Status</th><th>Submitted Date</th><th>Last Updated Date</th><th>Action</th></tr></thead><tbody>${rows}</tbody></table></div>`; }
