function performObservationPage() { return `${contextBar()}<div class="page-heading"><div><span class="eyebrow">OPEN OBSERVATIONS / PERFORM</span><h1>Perform Observation</h1><p>Complete the action required to close this observation.</p></div></div><section class="app-panel"><div class="metric-grid"><div><small>Observation</small><b>${observations[0]?.number || 'Open observation'}</b></div><div><small>Branch</small><b>${context.branch || 'Selected branch'}</b></div><div><small>Status</small><b>Open</b></div></div><form id="performObservationForm" class="form-grid"><label class="wide">Informed to Branch<textarea name="informed" rows="2" required placeholder="Enter how the branch was informed"></textarea></label><label class="wide">Action Taken<textarea name="actionTaken" rows="2" required placeholder="Enter action taken by the branch"></textarea></label><label class="wide">Attachment<input name="attachment" type="file"></label><div class="wide button-row"><button class="btn secondary" type="button" data-go="08-perform-audit-open-observations">Back to Open Observations</button><button class="btn primary" type="submit">Submit and Close Observation</button></div></form></section>`; }
function observationRuntime() { const form = document.getElementById('observationForm'); if (!form) return; const list = document.getElementById('observationList'); const render = () => { list.innerHTML = observations.length ? observations.map((item, index) => `<article><div><b>${item.number}</b><span>${item.voucher} · ${item.category} · ${item.amount}</span><p>${item.checkpoint} · ${item.remarks || 'No remarks'}</p></div><span><button type="button" data-edit="${index}">Edit</button><button type="button" data-delete="${index}">Delete</button></span></article>`).join('') : '<p class="empty-observations">No observations recorded for this audit instance.</p>'; }; form.onsubmit = event => { event.preventDefault(); const record = Object.fromEntries(new FormData(form).entries()); observations.push(record); saveAuditRecord({ observations, status: 'WIP', resumeStage: 4 }); form.reset(); render(); }; list.onclick = event => { const index = event.target.dataset.delete ?? event.target.dataset.edit; if (index === undefined) return; if (event.target.dataset.delete !== undefined && confirm('Delete this observation?')) observations.splice(Number(index), 1); else if (event.target.dataset.edit !== undefined) Object.entries(observations[Number(index)]).forEach(([key, value]) => { if (key !== 'attachment' && form.elements[key]) form.elements[key].value = value; }); saveAuditRecord({ observations, status: 'WIP', resumeStage: 4 }); render(); }; render(); }
