['observationFrom', 'observationTo', 'closedObservationFrom', 'closedObservationTo'].forEach(id => { const field = document.getElementById(id); if (field) field.onchange = () => { const container = field.closest('.audit-stage'); const from = new Date(container.querySelector('[id$="From"]').value || '1900-01-01'); const to = new Date(container.querySelector('[id$="To"]').value || '2999-12-31'); container.querySelectorAll('tbody tr[data-observation-date]').forEach(row => { const date = new Date(row.dataset.observationDate); row.hidden = date < from || date > to; }); }; });
