if (route === 13) { const form = document.getElementById('summaryForm'); const saved = auditRecord.summary || {}; const fallbackCurrency = { code: 'INR', name: 'Indian Rupee', major: 'Rupee', minor: 'Paise', factor: 100, cash: [1, 10, 20, 100, 500].map(value => ({ value, unit: value < 20 ? 'MINOR' : 'MAJOR', active: true })), atm: [100, 200, 500].map(value => ({ value, unit: 'MAJOR', active: true })) }; const currencies = JSON.parse(sessionStorage.getItem('currencyMasters') || '[]').filter(item => item.active !== false && item.code); const availableCurrencies = currencies.length ? currencies : [fallbackCurrency]; const selectedCode = saved.currency || availableCurrencies[0].code; const currency = () => availableCurrencies.find(item => item.code === form.elements.currency.value) || availableCurrencies[0]; const amount = (item, record) => Number(item.value) / (item.unit === 'MINOR' ? Number(record.factor || 1) : 1); const formatAmount = (value, record) => `${record.code} ${value.toFixed(2)}`; const denominationInput = (type, item, index, record) => { const savedEntry = saved.denominations?.[type]?.[index]; const savedValue = typeof savedEntry === 'object' ? savedEntry.quantity : savedEntry ?? 0; const unitName = item.unit === 'MINOR' ? record.minor || 'Minor Unit' : record.major || 'Major Unit'; return `<label>${record.code} ${item.value} ${unitName}<input class="${type}-note" data-note="${amount(item, record)}" data-denomination-type="${type}" data-denomination-index="${index}" type="number" min="0" step="1" value="${savedValue}"></label>`; }; const renderDenominations = () => { const record = currency(); const section = form.querySelector('.denomination-section'); const cash = (record.cash || []).filter(item => item.active !== false); const atm = (record.atm || []).filter(item => item.active !== false); section.innerHTML = `<div class="category-heading">${record.code} Cash Denomination Details</div><div class="denomination-grid">${cash.length ? cash.map((item, index) => denominationInput('cash', item, index, record)).join('') : '<p class="muted">No active cash denominations configured for this currency.</p>'}</div><label class="wide">Cash Remarks<textarea name="cashRemarks" rows="2">${saved.cashRemarks || ''}</textarea></label><div class="category-heading">${record.code} ATM Denomination Details</div><div class="denomination-grid">${atm.length ? atm.map((item, index) => denominationInput('atm', item, index, record)).join('') : '<p class="muted">No active ATM denominations configured for this currency.</p>'}</div><label class="wide">ATM Remarks<textarea name="atmRemarks" rows="2">${saved.atmRemarks || ''}</textarea></label>`; }; const selector = document.createElement('label'); selector.className = 'wide'; selector.innerHTML = `Currency<select name="currency">${availableCurrencies.map(item => `<option value="${item.code}" ${item.code === selectedCode ? 'selected' : ''}>${item.code} - ${item.name || item.major || ''}</option>`).join('')}</select>`; form.querySelector('.category-heading').before(selector); const section = document.createElement('div'); section.className = 'denomination-section wide'; form.querySelector('.summary-total').before(section); renderDenominations(); const summary = document.querySelector('.summary-total'); summary.innerHTML = `<div class="summary-total-line"><span>Cash denomination total</span><strong id="cashDenominationTotal"></strong></div><div class="summary-total-line"><span>ATM denomination total</span><strong id="atmDenominationTotal"></strong></div><div class="summary-total-line grand-total"><span>Grand total</span><strong id="summaryTotalValue"></strong></div>`; const calculate = () => { const record = currency(); const categoryTotal = ['cashManagement', 'kyc', 'vault'].reduce((sum, name) => sum + (Number(form.elements[name]?.value) || 0), 0); const cashTotal = [...form.querySelectorAll('.cash-note')].reduce((sum, input) => sum + Number(input.dataset.note) * (Number(input.value) || 0), 0); const atmTotal = [...form.querySelectorAll('.atm-note')].reduce((sum, input) => sum + Number(input.dataset.note) * (Number(input.value) || 0), 0); document.getElementById('cashDenominationTotal').textContent = formatAmount(cashTotal, record); document.getElementById('atmDenominationTotal').textContent = formatAmount(atmTotal, record); document.getElementById('summaryTotalValue').textContent = formatAmount(categoryTotal + cashTotal + atmTotal, record); document.getElementById('submitAudit').disabled = categoryTotal <= 0; }; form.elements.currency.onchange = () => { renderDenominations(); calculate(); }; form.oninput = calculate; form.onsubmit = event => { event.preventDefault(); if (document.getElementById('submitAudit').disabled) return; const record = currency(); const summaryData = Object.fromEntries(new FormData(form).entries()); summaryData.currency = record.code; summaryData.denominations = { cash: [...form.querySelectorAll('.cash-note')].map(input => ({ index: Number(input.dataset.denominationIndex), quantity: Number(input.value) || 0 })), atm: [...form.querySelectorAll('.atm-note')].map(input => ({ index: Number(input.dataset.denominationIndex), quantity: Number(input.value) || 0 })) }; saveContext({ status: 'Completed', summary: summaryData, completedAt: new Date().toISOString(), resumeStage: 5 }); saveAuditRecord({ status: 'Completed', summary: summaryData, observations, completedAt: new Date().toISOString(), resumeStage: 5 }); const shouldDownload = confirm('The audit has been submitted successfully. Would you like to download the generated Open Observations in Excel format for bulk closure?'); if (shouldDownload) downloadOpenObservations(); go('01-list-my-assigned-entities-populated'); }; calculate(); }
